import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  ArrowLeft, 
  Vote, 
  Users, 
  Clock, 
  Calendar,
  CheckCircle,
  XCircle,
  Shield,
  TrendingUp,
  BarChart3,
  AlertCircle
} from 'lucide-react';
import api from '../services/api';
import toast from 'react-hot-toast';

const ElectionDetail = () => {
  const { id } = useParams();
  const [election, setElection] = useState(null);
  const [loading, setLoading] = useState(true);
  const [voting, setVoting] = useState(false);
  const [selectedCandidate, setSelectedCandidate] = useState(null);
  const [showVoteModal, setShowVoteModal] = useState(false);
  const [secret, setSecret] = useState('');

  useEffect(() => {
    fetchElectionDetails();
  }, [id]);

  const fetchElectionDetails = async () => {
    try {
      const response = await api.get(`/api/elections/${id}`);
      setElection(response.data);
    } catch (error) {
      toast.error('Failed to load election details');
    } finally {
      setLoading(false);
    }
  };

  const getElectionStatus = () => {
    if (!election) return { status: 'loading', label: 'Loading', color: 'gray' };
    
    const now = Math.floor(Date.now() / 1000);
    const startTime = parseInt(election.startTime);
    const endTime = parseInt(election.endTime);

    if (now < startTime) {
      return { status: 'upcoming', label: 'Upcoming', color: 'blue' };
    } else if (now >= startTime && now <= endTime && election.isActive) {
      return { status: 'active', label: 'Active', color: 'green' };
    } else {
      return { status: 'ended', label: 'Ended', color: 'gray' };
    }
  };

  const formatDate = (timestamp) => {
    return new Date(parseInt(timestamp) * 1000).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleVote = async () => {
    if (!selectedCandidate) {
      toast.error('Please select a candidate');
      return;
    }

    if (!secret.trim()) {
      toast.error('Please enter a secret phrase');
      return;
    }

    setVoting(true);

    try {
      await api.post(`/api/elections/${id}/vote`, {
        candidateId: selectedCandidate.id,
        secret: secret
      });
      
      toast.success('Vote cast successfully!');
      setShowVoteModal(false);
      setSelectedCandidate(null);
      setSecret('');
      fetchElectionDetails(); // Refresh data
    } catch (error) {
      toast.error(error.response?.data?.error || 'Failed to cast vote');
    } finally {
      setVoting(false);
    }
  };

  const getVotePercentage = (voteCount) => {
    if (!election || parseInt(election.totalVotes) === 0) return 0;
    return Math.round((parseInt(voteCount) / parseInt(election.totalVotes)) * 100);
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.6,
        ease: "easeOut"
      }
    }
  };

  const cardVariants = {
    hidden: { scale: 0.8, opacity: 0 },
    visible: {
      scale: 1,
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="w-8 h-8 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!election) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 flex items-center justify-center">
        <div className="text-center">
          <AlertCircle className="w-16 h-16 mx-auto mb-4 text-gray-400" />
          <h2 className="text-2xl font-bold text-gray-900 mb-2">Election Not Found</h2>
          <p className="text-gray-600 mb-6">The election you're looking for doesn't exist.</p>
          <Link
            to="/elections"
            className="inline-flex items-center px-6 py-3 bg-purple-600 text-white font-medium rounded-lg hover:bg-purple-700 transition-colors"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Elections
          </Link>
        </div>
      </div>
    );
  }

  const status = getElectionStatus();

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={containerVariants}
          className="mb-8"
        >
          <motion.div variants={itemVariants} className="mb-6">
            <Link
              to="/elections"
              className="inline-flex items-center text-purple-600 hover:text-purple-700 mb-4 transition-colors"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Elections
            </Link>
            
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <h1 className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">
                  {election.name}
                </h1>
                <p className="text-gray-600 text-lg mb-4">
                  {election.description}
                </p>
                
                <div className="flex items-center space-x-6">
                  <div className="flex items-center space-x-2">
                    <Users className="w-5 h-5 text-gray-400" />
                    <span className="text-gray-600">{election.totalVotes} total votes</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Vote className="w-5 h-5 text-gray-400" />
                    <span className="text-gray-600">{election.candidates.length} candidates</span>
                  </div>
                </div>
              </div>
              
              <div className={`px-4 py-2 rounded-full text-sm font-medium ${
                status.color === 'green' ? 'bg-green-100 text-green-800' :
                status.color === 'blue' ? 'bg-blue-100 text-blue-800' :
                'bg-gray-100 text-gray-800'
              }`}>
                {status.label}
              </div>
            </div>
          </motion.div>

          {/* Election Info Card */}
          <motion.div variants={cardVariants} className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                  <Calendar className="w-5 h-5 text-blue-600" />
                </div>
                <div>
                  <div className="text-sm text-gray-500">Start Date</div>
                  <div className="font-medium text-gray-900">{formatDate(election.startTime)}</div>
                </div>
              </div>
              
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
                  <Clock className="w-5 h-5 text-red-600" />
                </div>
                <div>
                  <div className="text-sm text-gray-500">End Date</div>
                  <div className="font-medium text-gray-900">{formatDate(election.endTime)}</div>
                </div>
              </div>
              
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                  <TrendingUp className="w-5 h-5 text-green-600" />
                </div>
                <div>
                  <div className="text-sm text-gray-500">Status</div>
                  <div className="font-medium text-gray-900">{status.label}</div>
                </div>
              </div>
            </div>
          </motion.div>
        </motion.div>

        {/* Candidates Section */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={containerVariants}
          className="mb-8"
        >
          <motion.div variants={itemVariants} className="mb-6">
            <h2 className="text-2xl font-bold text-gray-900 mb-2">Candidates</h2>
            <p className="text-gray-600">Select your preferred candidate</p>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {election.candidates.map((candidate, index) => (
              <motion.div
                key={candidate.id}
                variants={cardVariants}
                whileHover={{ 
                  scale: 1.02,
                  transition: { duration: 0.2 }
                }}
                className={`bg-white rounded-2xl shadow-lg border-2 transition-all duration-200 cursor-pointer ${
                  selectedCandidate?.id === candidate.id
                    ? 'border-purple-500 shadow-purple-100'
                    : 'border-gray-100 hover:border-purple-200'
                }`}
                onClick={() => setSelectedCandidate(candidate)}
              >
                <div className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div className="w-12 h-12 bg-gradient-to-r from-purple-500 to-pink-500 rounded-full flex items-center justify-center text-white font-bold text-lg">
                      {candidate.name.charAt(0).toUpperCase()}
                    </div>
                    {selectedCandidate?.id === candidate.id && (
                      <CheckCircle className="w-6 h-6 text-purple-500" />
                    )}
                  </div>
                  
                  <h3 className="text-xl font-semibold text-gray-900 mb-2">
                    {candidate.name}
                  </h3>
                  
                  <div className="mb-4">
                    <div className="flex items-center justify-between text-sm text-gray-600 mb-2">
                      <span>Votes</span>
                      <span>{candidate.voteCount}</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-gradient-to-r from-purple-500 to-pink-500 h-2 rounded-full transition-all duration-300"
                        style={{ width: `${getVotePercentage(candidate.voteCount)}%` }}
                      ></div>
                    </div>
                    <div className="text-right text-sm text-gray-500 mt-1">
                      {getVotePercentage(candidate.voteCount)}%
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>

        {/* Vote Button */}
        {status.status === 'active' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center mb-8"
          >
            <button
              onClick={() => setShowVoteModal(true)}
              disabled={!selectedCandidate}
              className="inline-flex items-center px-8 py-4 bg-gradient-to-r from-purple-600 to-pink-600 text-white font-semibold rounded-lg hover:from-purple-700 hover:to-pink-700 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 transition-all duration-200 transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
            >
              <Vote className="w-5 h-5 mr-2" />
              Cast Your Vote
            </button>
          </motion.div>
        )}

        {/* Results Summary */}
        <motion.div
          initial="hidden"
          animate="visible"
          variants={cardVariants}
          className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100"
        >
          <h2 className="text-xl font-semibold text-gray-900 mb-6">Results Summary</h2>
          
          <div className="space-y-4">
            {election.candidates
              .sort((a, b) => parseInt(b.voteCount) - parseInt(a.voteCount))
              .map((candidate, index) => (
                <div key={candidate.id} className="flex items-center space-x-4">
                  <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center text-sm font-medium text-gray-600">
                    {index + 1}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center justify-between mb-1">
                      <span className="font-medium text-gray-900">{candidate.name}</span>
                      <span className="text-sm text-gray-600">{candidate.voteCount} votes</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-gradient-to-r from-purple-500 to-pink-500 h-2 rounded-full transition-all duration-300"
                        style={{ width: `${getVotePercentage(candidate.voteCount)}%` }}
                      ></div>
                    </div>
                  </div>
                </div>
              ))}
          </div>
        </motion.div>
      </div>

      {/* Vote Modal */}
      <AnimatePresence>
        {showVoteModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50"
            onClick={() => setShowVoteModal(false)}
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.8, opacity: 0 }}
              className="bg-white rounded-2xl p-6 w-full max-w-md"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="text-center mb-6">
                <Shield className="w-12 h-12 mx-auto mb-4 text-purple-600" />
                <h3 className="text-xl font-semibold text-gray-900 mb-2">Cast Your Vote</h3>
                <p className="text-gray-600">
                  You are voting for: <strong>{selectedCandidate?.name}</strong>
                </p>
              </div>

              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Secret Phrase
                </label>
                <input
                  type="text"
                  value={secret}
                  onChange={(e) => setSecret(e.target.value)}
                  placeholder="Enter a secret phrase for your vote"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                />
                <p className="text-xs text-gray-500 mt-1">
                  This secret will be used to verify your vote later
                </p>
              </div>

              <div className="flex space-x-3">
                <button
                  onClick={() => setShowVoteModal(false)}
                  className="flex-1 px-4 py-3 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleVote}
                  disabled={voting || !secret.trim()}
                  className="flex-1 px-4 py-3 bg-purple-600 text-white font-medium rounded-lg hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {voting ? 'Casting Vote...' : 'Confirm Vote'}
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default ElectionDetail;
